const $=s=>document.querySelector(s),key=location.pathname.split('/').filter(Boolean).find(part=>Object.hasOwn(PORTFOLIO,part))||'skoda',brand=PORTFOLIO[key],feed=$('#feed');
if(!brand){document.title='Project not found';feed.innerHTML='<div style="padding:30px">Project not found.<p><a href="/skoda">View selected work ↗</a></p></div>';}else{
document.title=brand.name+' — Campaign portfolio';document.body.style.setProperty('--accent',brand.color);
let current=0,sound=true;const paused=new Set();
brand.videos.forEach((item,i)=>{const el=document.createElement('section');el.className='film';el.dataset.index=i;el.setAttribute('aria-label',`Film ${i+1}: ${item.title}`);el.innerHTML=`<div class="stage" style="--ratio:${item.aspect||9/16}"><video playsinline webkit-playsinline loop preload="none" poster="${new URL(item.poster.replace(/^\//,''),document.baseURI).href}" aria-label="${item.title}"></video><img class="poster" src="${new URL(item.poster.replace(/^\//,''),document.baseURI).href}" alt="" loading="${i?'lazy':'eager'}"><div class="shade"></div><div class="filmhead">${item.sample?`<span class="sample">SAMPLE FILM ${String(i+1).padStart(2,'0')}</span>`:''}</div><div class="caption"><div class="eyebrow">${item.category||`${brand.category} · FILM ${String(i+1).padStart(2,'0')}`}</div><h2>${item.title}</h2><p>${item.description||''}</p><small>${item.role||''}</small></div><div class="status" role="status">Loading film…</div><div class="controls"><button class="play" aria-label="Pause video">Ⅱ</button><input type="range" min="0" max="100" step="0.1" value="0" aria-label="Video progress"><span class="time">0:00</span><button class="sound" aria-label="Mute sound" aria-pressed="true">♬</button></div></div>`;feed.append(el);const video=el.querySelector('video'),status=el.querySelector('.status'),play=el.querySelector('.play'),seek=el.querySelector('input'),mute=el.querySelector('.sound');video.muted=!sound;
function sync(){play.textContent=video.paused?'▶':'Ⅱ';play.setAttribute('aria-label',video.paused?'Play video':'Pause video')}
video.addEventListener('playing',()=>{if(i!==current||document.hidden||document.querySelector('dialog[open]')){video.pause();return}el.classList.add('playing');status.textContent='';sync()});video.addEventListener('pause',sync);video.addEventListener('waiting',()=>{status.textContent='Loading film…'});video.addEventListener('error',()=>{status.innerHTML='This film could not load.<button>Retry video</button>';status.querySelector('button').onclick=()=>{video.load();attempt(video)}});video.addEventListener('timeupdate',()=>{const delta=video.currentTime-(el.captionLastTime??video.currentTime);el.captionLastTime=video.currentTime;if(i===current&&!video.paused&&delta>0&&delta<1.5){el.captionElapsed=(el.captionElapsed||0)+delta;el.classList.toggle('caption-hidden',el.captionElapsed>=3)}seek.value=Number.isFinite(video.duration)?video.currentTime/video.duration*100:0;el.querySelector('.time').textContent=Math.floor(video.currentTime/60)+':'+String(Math.floor(video.currentTime%60)).padStart(2,'0')});seek.oninput=()=>{if(Number.isFinite(video.duration))video.currentTime=video.duration*seek.value/100};play.onclick=()=>{if(video.paused){paused.delete(i);attempt(video)}else{paused.add(i);video.pause()}};mute.onclick=()=>{setSound(!sound);if(sound)attempt(video)};el.querySelector('.shade').style.pointerEvents='auto';el.querySelector('.shade').onclick=()=>play.click();
const step=document.createElement('button');step.setAttribute('aria-label',`Go to film ${i+1}`);step.onclick=()=>go(i);$('#steps').append(step);
});
const films=[...feed.children];function load(i){const v=films[i]?.querySelector('video');if(v&&!v.src){v.src=new URL(brand.videos[i].src.replace(/^\//,''),document.baseURI).href;v.load()}return v}
function setSound(enabled){sound=enabled;document.querySelectorAll('video').forEach(v=>v.muted=!sound);document.querySelectorAll('.sound').forEach(b=>{b.textContent=sound?'♬':'♬̸';b.setAttribute('aria-label',sound?'Mute sound':'Enable sound');b.setAttribute('aria-pressed',String(sound))});document.querySelectorAll('.sound-prompt').forEach(b=>b.remove())}
function soundPrompt(v){const el=v.closest('.film');if(el.querySelector('.sound-prompt'))return;const b=document.createElement('button');b.className='sound-prompt';b.textContent='Tap for sound ♬';b.onclick=()=>{setSound(true);attempt(v)};el.querySelector('.stage').append(b)}
async function attempt(v){const active=()=>v.closest('.film').dataset.index==current&&!document.hidden&&!document.querySelector('dialog[open]');if(!active())return;v.muted=!sound;try{await v.play()}catch(error){if(!active()||v.error)return;if(error.name==='NotAllowedError'&&!v.muted){setSound(false);try{await v.play();if(active())soundPrompt(v);else v.pause();return}catch{}}if(!active())return;const s=v.closest('.film').querySelector('.status');s.innerHTML='Ready when you are.<button>Tap to play</button>';s.querySelector('button').onclick=()=>{paused.delete(current);attempt(v)}}}

function activate(i){if(current!==i){films[i].captionElapsed=0;films[i].captionLastTime=films[i].querySelector('video').currentTime;films[i].classList.remove('caption-hidden')}current=i;films.forEach((el,n)=>{if(n!==i)el.querySelector('video').pause()});[...$('#steps').children].forEach((b,n)=>{b.classList.toggle('active',n===i);b.setAttribute('aria-current',n===i?'true':'false')});const v=load(i);if(!document.hidden&&!paused.has(i)&&!document.querySelector('dialog[open]'))attempt(v)}
function go(i){const target=films[Math.max(0,Math.min(films.length-1,i))];feed.scrollTo({top:target.offsetTop,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}

const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting&&e.intersectionRatio>.65)activate(Number(e.target.dataset.index))})},{root:feed,threshold:[.65,.8]});films.forEach(el=>observer.observe(el));activate(0);
feed.addEventListener('keydown',e=>{if(e.target.matches('input,button'))return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();go(current+(e.key==='ArrowDown'?1:-1))}if(e.code==='Space'){e.preventDefault();films[current].querySelector('.play').click()}});document.addEventListener('visibilitychange',()=>{if(document.hidden)films.forEach(e=>e.querySelector('video').pause());else activate(current)});
}
